  const b = document.querySelector('#board-1 cg-board');
  const r = b.getBoundingClientRect();
  return { w: r.width, h: r.height };
});
// resize window and check the observer reacts (board re-sizes)
await page.setViewportSize({ width: 900, height: 700 });
await page.waitForTimeout(300);
const secondRect = await page.evaluate(() => {
  const b = document.querySelector('#board-1 cg-board');
  const r = b.getBoundingClientRect();
  return { w: r.width, h: r.height };
});
console.log('boards rendered:', count);
console.log('before resize:', JSON.stringify(firstRect));
console.log('after resize:', JSON.stringify(secondRect));
console.log('errors:', errors.length ? errors : 'none');
await browser.close();
EOF
